function evidence = f90_xrobo05_extract_reference_evidence( ...
    modelFile, officialScenarios, outDir)
%f90_xrobo05_extract_reference_evidence Public reference replay.
arguments
    modelFile (1,1) string
    officialScenarios (1,1) string
    outDir (1,1) string
end
assert(isfile(modelFile), "SimuVerity:F90:XROBO05:ModelMissing", ...
    "Reference model not found: %s", modelFile);
assert(isfile(officialScenarios), "SimuVerity:F90:XROBO05:ScenariosMissing", ...
    "Official scenario contract not found: %s", officialScenarios);
official = jsondecode(fileread(officialScenarios));
assert(string(official.task_id) == "F90-XROBO-05" && ...
    isfield(official, "scenarios") && numel(official.scenarios) == 6, ...
    "SimuVerity:F90:XROBO05:ScenarioBinding", ...
    "Exact F90-XROBO-05 official scenarios are required.");
scenarios = official.scenarios;
mssRoot = fileparts(fileparts(fileparts(modelFile)));
libraryFile = fullfile(mssRoot, "SIMULINK", "mssSimulink.slx");
plantFile = fullfile(mssRoot, "CRAFT", "AUV", "models", "remus100.m");
assert(strcmpi(localFilePresence(modelFile), ...
    "present"), ...
    "SimuVerity:F90:XROBO05:ModelBinding", "Pinned root-model binding mismatch.");
assert(strcmpi(localFilePresence(libraryFile), ...
    "present"), ...
    "SimuVerity:F90:XROBO05:LibraryBinding", "Pinned MSS library binding mismatch.");
assert(strcmpi(localFilePresence(plantFile), ...
    "present"), ...
    "SimuVerity:F90:XROBO05:PlantBinding", "Pinned REMUS plant binding mismatch.");

generationRunId = string(getenv("SIMUVERITY_GENERATION_RUN_ID"));
assert(strlength(generationRunId) > 0, "SimuVerity:F90:XROBO05:GenerationRunId", ...
    "SIMUVERITY_GENERATION_RUN_ID is required.");
assert(~isfolder(outDir), "SimuVerity:F90:XROBO05:OutputReuse", ...
    "Evidence output already exists: %s", outDir);
mkdir(outDir);

cacheDir = string(getenv("SIMULINK_CACHE_FOLDER"));
codegenDir = string(getenv("SIMULINK_CODEGEN_FOLDER"));
assert(strlength(cacheDir) > 0 && strlength(codegenDir) > 0, ...
    "SimuVerity:F90:XROBO05:Isolation", ...
    "Isolated cache and codegen folders are required.");
Simulink.fileGenControl("set", "CacheFolder", cacheDir, ...
    "CodeGenFolder", codegenDir, "createDir", true);
set(groot, "defaultFigureVisible", "off");
addpath(genpath(mssRoot), "-begin");

evidence = struct( ...
    "schema", "simuverity.f90-xrobo05-evidence.v1", ...
    "task_id", "F90-XROBO-05", ...
    "reference_substantive_modifications", 0, ...
    "extraction_only", true, ...
    "contains_score_decisions", false, ...
    "load_pass", false, ...
    "update_pass", false, ...
    "compile_pass", false, ...
    "nominal_smoke_pass", false, ...
    "static_audit", struct, ...
    "scenarios", struct([]), ...
    "errors", struct, ...
    "started_at", localNow, ...
    "runtime", struct( ...
        "generation_run_id", generationRunId, ...
        "matlab_release", string(version("-release")), ...
        "mcp_port", string(getenv("SIMUVERITY_MCP_PORT")), ...
        "matlab_prefdir", string(getenv("MATLAB_PREFDIR")), ...
        "cache", cacheDir, ...
        "codegen", codegenDir));

model = "demoAUVdepthHeadingControl";
try
    load_system(modelFile);
    cleanup = onCleanup(@() localCloseModel(model)); %#ok<NASGU>
    evidence.load_pass = true;
    paths = localModelPaths(model);
    localInstallMeasurementTaps(model, paths);
    set_param(model, ...
        "ReturnWorkspaceOutputs", "on", ...
        "StopTime", "400", ...
        "SignalLogging", "on", ...
        "SignalLoggingName", "logsout");
    localApplyScenario(paths, scenarios(1));
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;
    evidence.static_audit = localStaticAudit(paths);

    set_param(model, "StopTime", "10");
    smoke = sim(model, "ReturnWorkspaceOutputs", "on");
    localValidateSmoke(smoke);
    evidence.nominal_smoke_pass = true;
    clear smoke
    set_param(model, "StopTime", "400");

    rows = repmat(localEmptyScenario, numel(scenarios), 1);
    for k = 1:numel(scenarios)
        scenario = scenarios(k);
        rows(k).id = string(scenario.id);
        rows(k).requested_inputs = scenario;
        try
            localApplyScenario(paths, scenario);
            started = tic;
            simOut = sim(model, "ReturnWorkspaceOutputs", "on");
            rows(k).simulation_wall_clock_s = toc(started);
            outputs = localExtractOutputs(simOut);
            rows(k) = localFinalizeScenario(rows(k), outputs);
            clear simOut
        catch ME
            rows(k).error = localError(ME);
        end
    end
    evidence.scenarios = rows;
catch ME
    evidence.errors.session = localError(ME);
end

localCloseModel(model);
evidence.model_closed_without_save = ~bdIsLoaded(model);
evidence.finished_at = localNow;
evidencePath = fullfile(outDir, "evidence.json");
localWriteJson(evidencePath, evidence);
validCount = 0;
if ~isempty(evidence.scenarios)
    validCount = sum([evidence.scenarios.valid]);
end
fprintf("F90_XROBO05_EVIDENCE load=%d update=%d compile=%d smoke=%d valid=%d/%d path=%s\n", ...
    evidence.load_pass, evidence.update_pass, evidence.compile_pass, ...
    evidence.nominal_smoke_pass, validCount, ...
    numel(evidence.scenarios), evidencePath);
end

function paths = localModelPaths(model)
paths = struct( ...
    "heading_step", localFindRoot(model, "Desired heading (deg)"), ...
    "depth_step", localFindRoot(model, "Desired depth (m)"), ...
    "depth_filter", localFindRoot(model, "Transfer Fcn"), ...
    "heading_reference", localFindRoot(model, "Reference model"), ...
    "heading_autopilot", localFindRoot(model, "Heading autopilot"), ...
    "depth_autopilot", localFindRoot(model, "Depth autopilot"), ...
    "plant", localFindRoot(model, "Remus 100 AUV (remus100.m)"), ...
    "demux", localFindRoot(model, "Demux"), ...
    "actuator_mux", localFindRoot(model, "Mux1"), ...
    "depth_sign", localFindRoot(model, "Gain10"), ...
    "current_speed", localFindRoot(model, ...
        "Ocean current speed (m/s)"), ...
    "current_direction", localFindRoot(model, ...
        "Ocean current direction (rad)"), ...
    "propeller", localFindRoot(model, ...
        "propeller shaft speed (rpm)"));
end

function localInstallMeasurementTaps(model, paths)
localTap(model, paths.heading_step, 1, "f90_heading_command_deg");
localTap(model, paths.heading_reference, 1, "f90_heading_shaped_rad");
localTap(model, paths.depth_step, 1, "f90_depth_command_m");
localTap(model, paths.depth_filter, 1, "f90_depth_filtered_m");
localTap(model, paths.plant, 1, "f90_vehicle_state");
localTap(model, paths.plant, 2, "f90_vehicle_speed_mps");
localTap(model, paths.heading_autopilot, 1, "f90_rudder_rad");
localTap(model, paths.depth_autopilot, 1, "f90_stern_plane_rad");
localTap(model, paths.depth_autopilot, 2, "f90_desired_pitch_rad");
localTap(model, paths.propeller, 1, "f90_propeller_rpm");
localTap(model, paths.current_speed, 1, "f90_current_speed_mps");
localTap(model, paths.current_direction, 1, ...
    "f90_current_direction_rad");
end

function localTap(parent, source, port, variable)
tap = parent + "/F90 " + variable + " Tap";
assert(getSimulinkBlockHandle(tap) < 0, ...
    "SimuVerity:F90:XROBO05:TapCollision", ...
    "Temporary measurement tap already exists.");
add_block("simulink/Sinks/To Workspace", tap, ...
    "VariableName", variable, "SaveFormat", "Timeseries");
sourcePorts = get_param(source, "PortHandles");
tapPorts = get_param(tap, "PortHandles");
assert(sourcePorts.Outport(port) > 0 && tapPorts.Inport(1) > 0, ...
    "SimuVerity:F90:XROBO05:TapPort", "A required real source port is missing.");
add_line(parent, sourcePorts.Outport(port), tapPorts.Inport(1), ...
    "autorouting", "on");
end

function localApplyScenario(paths, scenario)
names = ["HeadingInitial_deg", "HeadingCommand_deg", ...
    "HeadingStepTime_s", "DepthInitial_m", "DepthCommand_m", ...
    "DepthStepTime_s", "CurrentSpeed_mps", ...
    "CurrentDirection_deg", "PropellerSpeed_rpm"];
for name = names
    assignin("base", name, double(scenario.(name)));
end
set_param(paths.heading_step, ...
    "Time", localNumber(scenario.HeadingStepTime_s), ...
    "Before", localNumber(scenario.HeadingInitial_deg), ...
    "After", localNumber(scenario.HeadingCommand_deg));
set_param(paths.depth_step, ...
    "Time", localNumber(scenario.DepthStepTime_s), ...
    "Before", localNumber(scenario.DepthInitial_m), ...
    "After", localNumber(scenario.DepthCommand_m));
set_param(paths.current_speed, ...
    "Value", localNumber(scenario.CurrentSpeed_mps));
set_param(paths.current_direction, ...
    "Value", localNumber(deg2rad(scenario.CurrentDirection_deg)));
set_param(paths.propeller, ...
    "Value", localNumber(scenario.PropellerSpeed_rpm));
end

function value = localNumber(value)
value = sprintf("%.17g", double(value));
end

function localValidateSmoke(simOut)
required = ["f90_heading_command_deg", "f90_heading_shaped_rad", ...
    "f90_depth_command_m", "f90_depth_filtered_m", ...
    "f90_vehicle_state", "f90_vehicle_speed_mps", ...
    "f90_rudder_rad", "f90_stern_plane_rad", ...
    "f90_desired_pitch_rad"];
for name = required
    value = localGetOutput(simOut, name);
    assert(isa(value, "timeseries") && numel(value.Time) >= 2, ...
        "SimuVerity:F90:XROBO05:SmokeTap", ...
        "Smoke run did not produce required Timeseries %s.", name);
end
constantInputs = ["f90_propeller_rpm", "f90_current_speed_mps", ...
    "f90_current_direction_rad"];
for name = constantInputs
    value = localGetOutput(simOut, name);
    assert(isa(value, "timeseries") && numel(value.Time) >= 1, ...
        "SimuVerity:F90:XROBO05:SmokeTap", ...
        "Smoke run did not produce required constant Timeseries %s.", name);
end
end

function outputs = localExtractOutputs(simOut)
headingRaw = localWorkspaceTimeseries(simOut, ...
    "f90_heading_command_deg", 1);
headingShaped = localWorkspaceTimeseries(simOut, ...
    "f90_heading_shaped_rad", 1);
depthRaw = localWorkspaceTimeseries(simOut, ...
    "f90_depth_command_m", 1);
depthFiltered = localWorkspaceTimeseries(simOut, ...
    "f90_depth_filtered_m", 1);
vehicle = localWorkspaceTimeseries(simOut, "f90_vehicle_state", 12);
speed = localWorkspaceTimeseries(simOut, ...
    "f90_vehicle_speed_mps", 1);
rudder = localWorkspaceTimeseries(simOut, "f90_rudder_rad", 1);
stern = localWorkspaceTimeseries(simOut, ...
    "f90_stern_plane_rad", 1);
pitchCommand = localWorkspaceTimeseries(simOut, ...
    "f90_desired_pitch_rad", 1);
propeller = localWorkspaceTimeseries(simOut, ...
    "f90_propeller_rpm", 1);
currentSpeed = localWorkspaceTimeseries(simOut, ...
    "f90_current_speed_mps", 1);
currentDirection = localWorkspaceTimeseries(simOut, ...
    "f90_current_direction_rad", 1);

time = linspace(0, 400, 8001)';
outputs = struct( ...
    "time_s", time, ...
    "reference_state", [ ...
        localInterp(headingRaw, time), ...
        localInterp(headingShaped, time), ...
        localInterp(depthRaw, time), ...
        localInterp(depthFiltered, time)], ...
    "vehicle_state", localInterp(vehicle, time), ...
    "actuation_state", [ ...
        localInterp(rudder, time), ...
        localInterp(stern, time), ...
        localInterp(pitchCommand, time), ...
        localInterp(propeller, time)], ...
    "environment_state", [ ...
        localInterp(currentSpeed, time), ...
        localInterp(currentDirection, time), ...
        localInterp(speed, time)]);
end

function row = localFinalizeScenario(row, outputs)
allValues = [outputs.time_s; outputs.reference_state(:); ...
    outputs.vehicle_state(:); outputs.actuation_state(:); ...
    outputs.environment_state(:)];
row.simulation_pass = true;
row.required_evidence_pass = all(isfinite(allValues)) && ...
    numel(outputs.time_s) == 8001 && ...
    outputs.time_s(1) == 0 && outputs.time_s(end) >= 400;
row.valid = row.required_evidence_pass;
row.sample_count = numel(outputs.time_s);
row.start_time_s = outputs.time_s(1);
row.end_time_s = outputs.time_s(end);
row.outputs = outputs;
row.error = struct;
end

function audit = localStaticAudit(paths)
audit = struct( ...
    "pinned_remus_plant_block", ...
        getSimulinkBlockHandle(paths.plant) > 0, ...
    "heading_autopilot_block", ...
        getSimulinkBlockHandle(paths.heading_autopilot) > 0, ...
    "depth_autopilot_block", ...
        getSimulinkBlockHandle(paths.depth_autopilot) > 0, ...
    "heading_to_rudder_mux", ...
        localPortConnects(paths.heading_autopilot, 1, ...
        paths.actuator_mux, 1), ...
    "depth_to_stern_mux", ...
        localPortConnects(paths.depth_autopilot, 1, ...
        paths.depth_sign, 1) && ...
        localPortConnects(paths.depth_sign, 1, ...
        paths.actuator_mux, 2), ...
    "propeller_to_actuator_mux", ...
        localPortConnects(paths.propeller, 1, ...
        paths.actuator_mux, 3), ...
    "actuator_mux_to_plant", ...
        localPortConnects(paths.actuator_mux, 1, paths.plant, 1), ...
    "current_speed_to_plant", ...
        localPortConnects(paths.current_speed, 1, paths.plant, 3), ...
    "current_direction_to_plant", ...
        localPortConnects(paths.current_direction, 1, paths.plant, 4), ...
    "plant_state_to_demux", ...
        localPortConnects(paths.plant, 1, paths.demux, 1), ...
    "heading_feedback_present", ...
        localPortConnects(paths.demux, 6, paths.heading_autopilot, 5) && ...
        localPortConnects(paths.demux, 12, paths.heading_autopilot, 4), ...
    "depth_feedback_present", ...
        localPortConnects(paths.demux, 5, paths.depth_autopilot, 1) && ...
        localPortConnects(paths.demux, 11, paths.depth_autopilot, 3) && ...
        localPortConnects(paths.demux, 9, paths.depth_autopilot, 4));
values = struct2cell(audit);
audit.core_path_qualified = all(cellfun(@(value) logical(value), values));
end

function pass = localPortConnects(source, outIndex, destination, inIndex)
pass = false;
try
    sourcePorts = get_param(source, "PortHandles");
    destinationPorts = get_param(destination, "PortHandles");
    line = get_param(sourcePorts.Outport(outIndex), "Line");
    destinations = get_param(line, "DstPortHandle");
    pass = any(destinations == destinationPorts.Inport(inIndex));
catch
end
end

function path = localFindRoot(model, expected)
blocks = find_system(model, "SearchDepth", 1, "Type", "Block");
matches = strings(0, 1);
for k = 1:numel(blocks)
    name = string(get_param(blocks{k}, "Name"));
    normalized = strtrim(regexprep(name, "\s+", " "));
    if strcmpi(normalized, expected)
        matches(end + 1, 1) = string(blocks{k}); %#ok<AGROW>
    end
end
assert(numel(matches) == 1, "SimuVerity:F90:XROBO05:BlockLookup", ...
    "Expected one root block named %s, found %d.", ...
    expected, numel(matches));
path = matches(1);
end

function series = localWorkspaceTimeseries(simOut, name, columns)
value = localGetOutput(simOut, name);
assert(isa(value, "timeseries"), "SimuVerity:F90:XROBO05:WorkspaceTap", ...
    "Required measurement tap %s is missing.", name);
data = squeeze(double(value.Data));
if isvector(data), data = data(:); end
if size(data, 1) ~= numel(value.Time) && ...
        size(data, 2) == numel(value.Time)
    data = data.';
end
assert(size(data, 1) == numel(value.Time) && ...
    size(data, 2) == columns, "SimuVerity:F90:XROBO05:WorkspaceShape", ...
    "Tap %s has unexpected dimensions.", name);
series = struct( ...
    "time", double(value.Time(:)), ...
    "values", data);
end

function values = localInterp(series, time)
assert(~isempty(series.time) && ~isempty(series.values), ...
    "SimuVerity:F90:XROBO05:EmptySeries", "Required series is empty.");
if numel(series.time) == 1
    values = repmat(series.values(1, :), numel(time), 1);
    return
end
values = interp1(series.time, series.values, time, ...
    "linear", "extrap");
end

function value = localGetOutput(simOut, name)
value = [];
try, value = simOut.get(name); catch, end
if isempty(value)
    try, value = evalin("base", name); catch, end
end
end

function row = localEmptyScenario
row = struct( ...
    "id", "", ...
    "requested_inputs", struct, ...
    "simulation_pass", false, ...
    "required_evidence_pass", false, ...
    "valid", false, ...
    "simulation_wall_clock_s", 0, ...
    "sample_count", 0, ...
    "start_time_s", 0, ...
    "end_time_s", 0, ...
    "outputs", struct, ...
    "error", struct);
end

function info = localError(ME)
info = struct("identifier", string(ME.identifier), ...
    "message", string(ME.message));
end

function localCloseModel(model)
try
    if bdIsLoaded(model), close_system(model, 0); end
catch
end
end

function binding = localFilePresence(path)
assert(isfile(path), "SimuVerity:FileMissing", "Required file is missing: %s", path);
binding = "present";
end

function localWriteJson(path, value)
fid = fopen(path, "w");
assert(fid > 0, "SimuVerity:F90:XROBO05:JsonWrite", ...
    "Could not open JSON output: %s", path);
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
bytes = unicode2native(jsonencode(value, PrettyPrint=true), "UTF-8");
fwrite(fid, bytes, "uint8");
end

function value = localNow
value = string(datetime("now", ...
    "TimeZone", "Asia/Shanghai", ...
    "Format", "yyyy-MM-dd'T'HH:mm:ssXXX"));
end
